                # We'll validate this after parsing minutes and seconds
                comps['hour'] = 0
                comps['_24_hour'] = True
            else:
                if time_part > 23:
                    raise ValueError('hour must be in 0..23')
                comps['hour'] = time_part
                comps['_24_hour'] = False
        elif i == 1:
            if time_part > 59:
                raise ValueError('minute must be in 0..59')
            comps['minute'] = time_part
        elif i == 2:
            if time_part > 59:
                raise ValueError('second must be in 0..59')
            comps['second'] = time_part

        pos += directive_len

        if i < 2:
