                pos += 1

    if comps.get('_24_hour'):
        if comps.get('minute', 0) != 0 or comps.get('second', 0) != 0:
            raise ValueError('24:00:00 can only be represented with 00 minutes and 00 seconds')
        del comps['_24_hour']

    # Handle fractional seconds
    frac = None
