def _parse_time(self, timestr):
    # This is adapted from the ABNF in RFC 3339 Appendix A and Python's
    # datetime.fromisoformat()
    len_str = len(timestr)
    pos = 0
    comps = {}

    for (i, comp_re) in enumerate((
            re.compile(br'(?P<hour>[0-9]{2})(?::?(?P<minute>[0-9]{2})(?::?(?P<second>[0-9]{2}(?:[.,][0-9]{1,6})?))?)?'),
            re.compile(br'(?P<tzoffset>Z|[+-][0-9]{2}:[0-9]{2}|(?:[+-][0-9]{2})?[0-9]{2})'))):
        m = comp_re.match(timestr[pos:])
        if not m:
            break
        comps.update(m.groupdict())
        pos += m.end()

    if pos == 0:
        raise ValueError('Invalid time format')

    hour = int(comps.get('hour') or 0)
    minute = int(comps.get('minute') or 0)
    second = comps.get('second') or 0

    if isinstance(second, bytes):
        second = second.decode()

    frac = 0
    if ',' in second or '.' in second:
        splitter = '[.,]'
        second, frac = re.split(splitter, second)
        second = int(second)

        # Pad or truncate to 6 digits
        frac = frac.ljust(6, b'0' if isinstance(frac, bytes) else '0')
        frac = frac[:6]
        frac = int(frac)
    else:
        second = int(second)

    # Allow hour to be 24 for midnight representation (ISO 8601)
    if not (0 <= hour <= 24):
        raise ValueError('hour must be in 0..24')
    if not (0 <= minute <= 59):
        raise ValueError('minute must be in 0..59')
    if not (0 <= second <= 59):
        raise ValueError('second must be in 0..59')

    tzoffset = comps.get('tzoffset')
    if tzoffset:
        if tzoffset == b'Z':
            tzi = tz.tzutc()
        else:
            if isinstance(tzoffset, bytes):
                tzoffset = tzoffset.decode()
            # This is adapted from datetime.fromisoformat()
            try:
                offset_mins = int(tzoffset[-2:])
                offset_hrs = int(tzoffset[-5:-3])
                signal = -1 if tzoffset[0] == '-' else 1
                offset = signal * (3600 * offset_hrs + 60 * offset_mins)
                tzi = tz.tzoffset(None, offset)
            except (ValueError, IndexError):
                raise ValueError('Malformed time zone offset')
    else:
        tzi = None

    if pos < len_str:
        raise ValueError('Trailing characters in time portion')

    return (hour, minute, second, frac, tzi)

